// Audit reproducer for an OPEN defect, not a product acceptance test.
// Original Core, Git, ArtifactStore, journal recovery and authorization execute.
// The existing deterministic checker fixture emits contract-valid Unicode keys
// inside reason.details. No model/provider or native-gate success is claimed.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { budgetFixture } from '../../../../tests/verification/reliability/repair-budget-fixture.mjs';
import { runPipelineV2 } from '../../../../skills/nova/core/execution/engine.ts';
import { runRoot } from '../../../../skills/nova/core/execution/run-root.ts';
import { FileJournal } from '../../../../skills/nova/core/state/journal.ts';
import { recoverStageStates } from '../../../../skills/nova/core/lifecycle/recovery.ts';
import { authorizedRepair } from '../../../../skills/nova/core/lifecycle/repair-authorization.ts';
import { validateContractValue } from '@kubeclaw/plugin-foundation/registry/schema';

const script = fileURLToPath(import.meta.url);
const [mode, root] = process.argv.slice(2);
if (mode === '--produce') {
  const f = budgetFixture(root, { lint: [1, 2, 3] });
  // This is a test plugin's deterministic finding body, not a core-code edit.
  // Its result schema delegates to the production StageResult validator, whose
  // reason.details is an unconstrained JSON object. Source facts stay unchanged.
  const checker = path.join(root, 'plugins', 'plugin', 'stage.mjs');
  const source = fs.readFileSync(checker, 'utf8');
  assert.equal(source.split('details: { version, revision }').length, 2);
  fs.writeFileSync(checker, source.replace('details: { version, revision }', "details: { version, revision, 'ä': 2, z: 1 }"));
  const runId = 'run:repair-authorization-locale';
  const result = await runPipelineV2(f.platform, f.definition, runId);
  assert.equal(result.status, 'waiting');
  const state = result.stages.get('lint');
  const pending = state.pendingRepair;
  validateContractValue('stageResult', pending.request.requesterResult);
  assert.equal(pending.request.requesterResult.reason.details.ä, 2);
  const wait = state.wait;
  const signal = { schemaVersion: 'resume-signal.v2', signalId: 'signal:original', idempotencyKey: 'key:original',
    waitId: wait.waitId, signalType: wait.signalType, issuer: wait.authorizedIssuer, issuedAt: new Date().toISOString(),
    payload: { repairAuthorization: { pendingDigest: wait.request.repairAuthorization.digest, reason: 'Authorize this exact persisted finding.' } } };
  assert.equal(authorizedRepair(f.definition.stages, result.stages, state, signal).budgetOrder.id, pending.digest);
  fs.writeFileSync(path.join(root, 'case.json'), JSON.stringify({ runId, definition: f.definition,
    journal: path.join(runRoot(f.platform.storageRoot, runId), 'events.jsonl'), signal, digest: pending.digest }));
  process.stdout.write(JSON.stringify({ locale: Intl.DateTimeFormat().resolvedOptions().locale,
    state: result.status, originalDigest: pending.digest, sourceAttempts: result.stages.get('source').attemptsUsed }));
} else if (mode === '--read') {
  const stored = JSON.parse(fs.readFileSync(path.join(root, 'case.json'), 'utf8'));
  const states = recoverStageStates(stored.definition, new FileJournal(stored.journal).records(), stored.runId, 'nova');
  const pending = states.get('lint').pendingRepair;
  let error;
  try { authorizedRepair(stored.definition.stages, states, states.get('lint'), stored.signal); }
  catch (caught) { error = caught.message; }
  process.stdout.write(JSON.stringify({ locale: Intl.DateTimeFormat().resolvedOptions().locale,
    originalDigest: stored.digest, recoveredDigest: pending.digest,
    originalWaitDigest: states.get('lint').wait.request.repairAuthorization.digest,
    authorized: error === undefined, ...(error ? { error } : {}) }));
} else {
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'repair-locale-audit-'));
  const invoke = (operation, locale) => {
    const env = { ...process.env, LANG: locale, LC_ALL: locale }; delete env.NODE_TEST_CONTEXT;
    return JSON.parse(execFileSync(process.execPath, [script, operation, temporary], { cwd: path.resolve('.'), env, encoding: 'utf8', timeout: 120000 }));
  };
  try {
    const producer = invoke('--produce', 'en_US.UTF-8');
    const stored = JSON.parse(fs.readFileSync(path.join(temporary, 'case.json'), 'utf8'));
    const originalJournal = fs.readFileSync(stored.journal);
    const english = invoke('--read', 'en_US.UTF-8');
    const swedish = invoke('--read', 'sv_SE.UTF-8');
    assert.equal(producer.locale, 'en-US'); assert.equal(english.locale, 'en-US'); assert.equal(swedish.locale, 'sv-SE');
    assert.equal(english.authorized, true);
    assert.equal(english.originalDigest, english.recoveredDigest);
    assert.equal(swedish.originalDigest, swedish.originalWaitDigest);
    assert.notEqual(swedish.originalDigest, swedish.recoveredDigest);
    assert.equal(swedish.authorized, false);
    assert.equal(swedish.error, 'REPAIR_AUTHORIZATION_INVALID');
    assert.deepEqual(fs.readFileSync(stored.journal), originalJournal);
    process.stdout.write(`${JSON.stringify({ reproducedOpenDefect: true, producer, english, swedish,
      journalUnchanged: true, completePipelineOrNativeProof: false }, null, 2)}\n`);
  } finally { fs.rmSync(temporary, { recursive: true, force: true }); }
}

import type { AdministrativeReopenDecision, LifecycleEvent, PipelineDefinition, PluginDomainEvent, StageResult } from '@kubeclaw/plugin-sdk';
import { validateContractValue } from '@kubeclaw/plugin-foundation/registry/schema';
import { repairRequest, type RepairRequest } from '../lifecycle/remediation.ts';
import type { FileJournal } from '../state/journal.ts';
import type { StageRuntimeState } from '../lifecycle/reducer.ts';
import { pendingRepair, repairDisposition, repairOrder } from '../lifecycle/repair-budget.ts';

/** The authorized repair carries the original durable findings, not a synthetic pass. */
export function administrativeRepairRequest(definition: PipelineDefinition, decision: AdministrativeReopenDecision,
  events: FileJournal<LifecycleEvent | PluginDomainEvent>, generation: number, states?: ReadonlyMap<string, StageRuntimeState>): RepairRequest {
  if (decision.continuation !== 'remediation') throw new Error('ADMIN_REMEDIATION_DECISION_REQUIRED');
  const completion = [...events.records()].reverse().find(({ entry }) => entry.schemaVersion === 'lifecycle-event.v2'
    && entry.identity.runId === decision.runId && entry.identity.stageId === decision.stageId
    && ['attempt.completed', 'attempt.cancelled', 'attempt.timed_out'].includes(entry.type));
  const result = completion?.entry.payload.result;
  if (!result) throw new Error(`ADMIN_REMEDIATION_EVIDENCE_MISSING:${decision.stageId}`);
  validateContractValue('stageResult', result);
  const stage = definition.stages.find(candidate => candidate.id === decision.stageId)!;
  if (stage.execution.repairCategory) {
    const current = states?.get(stage.id);
    if (!current) throw new Error('ADMIN_REPAIR_STATE_REQUIRED');
    const pending = pendingRepair(definition.stages, states!, stage, { ...current, remediationCyclesUsed: generation }, result as StageResult, decision.runId);
    if (repairDisposition(definition.stages, pending) !== 'allowed') throw new Error('ADMIN_REPAIR_BUDGET_EXHAUSTED');
    return { ...pending.request, budgetOrder: repairOrder(pending, current.attemptNumber) };
  }
  return repairRequest(definition.stages, decision.stageId, decision.remediationStageId, generation, result as StageResult);
}

import { applyRepair, repairRequest } from '../lifecycle/remediation.ts';
import { budgetedRepairDecision } from '../lifecycle/repair-budget.ts';
import type { ExecutionGraph } from './graph.ts';
import { decisionWait } from '../lifecycle/wait-request.ts';
import type { LifecycleEvent, StageDefinition, StageResult } from '@kubeclaw/plugin-sdk';
import type { LifecycleDecision, StageRuntimeState } from '../lifecycle/reducer.ts';
import type { ArtifactCheckpointRecorder } from './artifact-checkpoints.ts';
import type { AppendLifecycleEvent } from './stage-executor.ts';

export interface CompletedStageDecision {
  readonly definition: StageDefinition;
  readonly decision: LifecycleDecision & { readonly result: StageResult };
  readonly administrativeOverride: boolean;
}

type TerminalStatus = 'failed' | 'blocked' | 'cancelled';
export interface BatchOutcome { readonly terminal?: TerminalStatus; readonly paused: boolean }

export class DecisionRecorder {
  readonly #graph: ExecutionGraph;
  readonly #states: Map<string, StageRuntimeState>; readonly #append: AppendLifecycleEvent; readonly #issuer: string;
  readonly #force: (stageId: string) => void; readonly #checkpoints: ArtifactCheckpointRecorder;
  #terminal: TerminalStatus | undefined; #paused = false;
  constructor(states: Map<string, StageRuntimeState>, append: AppendLifecycleEvent, issuer: string,
    force: (stageId: string) => void, checkpoints: ArtifactCheckpointRecorder, graph: ExecutionGraph) {
    this.#graph = graph; this.#states = states; this.#append = append; this.#issuer = issuer; this.#force = force; this.#checkpoints = checkpoints;
  }

  record(runId: string, completed: CompletedStageDecision): void {
    const { definition, administrativeOverride } = completed;
    const decision = { ...budgetedRepairDecision(this.#graph.stages(), this.#states, definition, completed.decision, completed.decision.result, runId), result: completed.decision.result };
    completed = { ...completed, decision };
    this.#states.set(definition.id, decision.state); this.#artifacts(runId, definition.id, decision.result);
    if (administrativeOverride && !['complete', 'stop'].includes(decision.action.type)) { this.#administrativeBlocked(runId, definition.id, decision.state); return; }
    const handler = this.#handlers()[decision.action.type]; handler(runId, completed);
  }

  outcome(): BatchOutcome { return { ...(this.#terminal ? { terminal: this.#terminal } : {}), paused: this.#paused }; }

  #handlers(): Record<LifecycleDecision['action']['type'], (runId: string, completed: CompletedStageDecision) => void> {
    return {
      schedule_attempt: (runId, completed) => this.#retry(runId, completed),
      schedule_remediation: (runId, completed) => this.#remediate(runId, completed),
      request_orchestrator: (runId, completed) => this.#orchestrator(runId, completed),
      pause_for_orchestrator: (runId, completed) => this.#orchestrator(runId, completed),
      request_repair_authorization: (runId, completed) => this.#orchestrator(runId, completed),
      persist_wait: (runId, completed) => this.#wait(runId, completed), cooldown: (runId, completed) => this.#wait(runId, completed),
      stop: (runId, completed) => this.#stop(runId, completed), complete: (runId, completed) => this.#complete(runId, completed),
    };
  }

  #artifacts(runId: string, stageId: string, result: StageResult): void {
    this.#checkpoints.completedResult(runId, stageId, result);
  }

  #administrativeBlocked(runId: string, stageId: string, state: StageRuntimeState): void {
    const blocked = { ...state, status: 'blocked' as const }; this.#states.set(stageId, blocked);
    this.#append('stage.blocked', { runId, stageId }, { attemptsUsed: blocked.attemptsUsed, remediationCyclesUsed: blocked.remediationCyclesUsed, reason: 'administrative_attempt_consumed' });
    this.#recordTerminal('blocked');
  }

  #retry(runId: string, { definition, decision }: CompletedStageDecision): void {
    this.#states.set(definition.id, { ...decision.state, status: 'pending' });
    this.#append('stage.retrying', { runId, stageId: definition.id }, { attemptsUsed: decision.state.attemptsUsed, remediationCyclesUsed: decision.state.remediationCyclesUsed });
    this.#force(definition.id);
  }

  #remediate(runId: string, { definition, decision }: CompletedStageDecision): void {
    if (decision.action.type !== 'schedule_remediation') return;
    const targetId = decision.action.stageId; const remediation = this.#states.get(targetId)!;
    if (['blocked', 'failed', 'cancelled'].includes(remediation.status)) { this.#terminalRemediation(runId, definition.id, targetId, decision.state, remediation.status); return; }
    const request = decision.action.repairRequest ?? repairRequest(this.#graph.stages(), definition.id, targetId, decision.state.remediationCyclesUsed, decision.result);
    if (remediation.remediationReturnTo && remediation.remediationReturnTo !== definition.id) {
      this.#terminalRemediation(runId, definition.id, targetId, decision.state, 'blocked'); return;
    }
    this.#append('stage.waiting', { runId, stageId: definition.id }, { attemptsUsed: decision.state.attemptsUsed,
      remediationCyclesUsed: decision.state.remediationCyclesUsed, remediationStageId: targetId, repairRequest: request });
    applyRepair(this.#states, request); this.#force(targetId);
  }

  #terminalRemediation(runId: string, stageId: string, targetId: string, state: StageRuntimeState, targetStatus: StageRuntimeState['status']): void {
    const blocked = { ...state, status: 'blocked' as const }; this.#states.set(stageId, blocked);
    this.#append('stage.blocked', { runId, stageId }, { attemptsUsed: blocked.attemptsUsed, remediationCyclesUsed: blocked.remediationCyclesUsed, remediationStageId: targetId, reason: 'remediation_target_terminal' });
    this.#recordTerminal(targetStatus === 'failed' ? 'failed' : targetStatus === 'cancelled' ? 'cancelled' : 'blocked');
  }

  #orchestrator(runId: string, { definition, decision }: CompletedStageDecision): void {
    const action = decision.action;
    if (action.type !== 'request_orchestrator' && action.type !== 'pause_for_orchestrator' && action.type !== 'request_repair_authorization') return;
    const wait = decisionWait(decision, runId, this.#issuer)!;
    this.#states.set(definition.id, { ...decision.state, wait });
    this.#append('orchestrator.required', { runId, stageId: definition.id }, { ...(action.type === 'request_orchestrator' ? { afterAttempt: action.afterAttempt } : {}),
      attemptsUsed: decision.state.attemptsUsed, remediationCyclesUsed: decision.state.remediationCyclesUsed, wait }); this.#paused = true;
  }

  #wait(runId: string, { definition, decision }: CompletedStageDecision): void {
    const action = decision.action;
    if (action.type !== 'persist_wait' && action.type !== 'cooldown') return;
    this.#append('stage.waiting', { runId, stageId: definition.id }, { attemptsUsed: decision.state.attemptsUsed,
      remediationCyclesUsed: decision.state.remediationCyclesUsed, ...(action.type === 'persist_wait' ? { wait: action.wait } : { retryAt: action.retryAt }) });
    this.#paused = true;
  }

  #stop(runId: string, { definition, decision }: CompletedStageDecision): void {
    const status: TerminalStatus = decision.state.status === 'blocked' ? 'blocked' : decision.state.status === 'cancelled' ? 'cancelled' : 'failed';
    this.#append(`stage.${status}` as LifecycleEvent['type'], { runId, stageId: definition.id }, { stageType: definition.type,
      ...(typeof definition.config.agentRole === 'string' ? { agentRole: definition.config.agentRole } : {}), outcome: decision.result.outcome,
      reason: decision.result.reason, attemptsUsed: decision.state.attemptsUsed, remediationCyclesUsed: decision.state.remediationCyclesUsed });
    this.#recordTerminal(status);
  }

  #complete(runId: string, { definition, decision }: CompletedStageDecision): void {
    this.#append('stage.succeeded', { runId, stageId: definition.id }, { stageType: definition.type,
      ...(typeof definition.config.agentRole === 'string' ? { agentRole: definition.config.agentRole } : {}), outcome: decision.result.outcome,
      attemptsUsed: decision.state.attemptsUsed, remediationCyclesUsed: decision.state.remediationCyclesUsed,
      ...(decision.state.facts ? { facts: decision.state.facts } : {}), ...(decision.state.remediationReturnTo ? { remediationReturnTo: decision.state.remediationReturnTo } : {}) });
    if (decision.state.remediationReturnTo) this.#completeRemediation(runId, definition.id, decision.state);
  }

  #completeRemediation(runId: string, stageId: string, state: StageRuntimeState): void {
    const returnTo = state.remediationReturnTo!; const requester = this.#states.get(returnTo);
    if (!requester) throw new Error(`GRAPH_REMEDIATION_RETURN_MISSING:${returnTo}`);
    const { remediationReturnTo: _returnTo, ...withoutReturn } = state; const { remediationTarget: _target, ...requesterWithoutTarget } = requester;
    this.#states.set(stageId, withoutReturn); this.#states.set(returnTo, { ...requesterWithoutTarget, status: 'pending' });
    this.#append('stage.scheduled', { runId, stageId: returnTo }, { reason: 'remediation_completed', remediationStageId: stageId });
  }

  #recordTerminal(status: TerminalStatus): void {
    const priority = { cancelled: 1, blocked: 2, failed: 3 } as const;
    if (!this.#terminal || priority[status] > priority[this.#terminal]) this.#terminal = status;
  }
}

import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import type { ArtifactRef, AttemptIdentity, InvocationLease, LifecycleEvent, PluginContext, PluginDomainEvent, StageResult } from '@kubeclaw/plugin-sdk';
import type { ActivatedRegistry } from '@kubeclaw/plugin-foundation/registry/activation';
import type { GrantedRegistry } from '@kubeclaw/plugin-foundation/registry/capabilities';
import { validateReferencedValue } from '@kubeclaw/plugin-foundation/registry/schema';
import { applyStageResult, type StageRuntimeState } from '../lifecycle/reducer.ts';
import type { FileJournal } from '../state/journal.ts';
import { artifactFromWrite, type ArtifactCheckpointRecorder } from './artifact-checkpoints.ts';
import { createPluginInvocationContext } from './context.ts';
import type { AdapterRuntime } from './adapters.ts';
import type { ExecutionGraph } from './graph.ts';
import { RevocableLease } from './lease.ts';

export type AppendLifecycleEvent = (type: LifecycleEvent['type'], identity: LifecycleEvent['identity'], payload?: Readonly<Record<string, unknown>>, causationId?: string | null) => LifecycleEvent;

interface ExecutorOptions {
  readonly graph: ExecutionGraph; readonly registry: GrantedRegistry; readonly activated: ActivatedRegistry; readonly adapters: AdapterRuntime;
  readonly journal: FileJournal<LifecycleEvent | PluginDomainEvent>; readonly signal?: AbortSignal; readonly now: () => Date; readonly append: AppendLifecycleEvent;
  readonly checkpoints: ArtifactCheckpointRecorder;
}

interface AttemptRuntime {
  readonly attempt: AttemptIdentity; readonly leaseContract: InvocationLease; readonly lease: RevocableLease;
  readonly controller: AbortController; readonly cancellation: Promise<never>; readonly cancel: () => void; readonly context: ReturnType<typeof createPluginInvocationContext>;
}

export class StageExecutor {
  readonly #options: ExecutorOptions;
  constructor(options: ExecutorOptions) { this.#options = options; }

  async execute(runId: string, state: StageRuntimeState, guidance?: Readonly<Record<string, unknown>>): Promise<{ state: StageRuntimeState; action: ReturnType<typeof applyStageResult>['action']; result: StageResult }> {
    const definition = this.#options.graph.stage(state.stageId);
    const owner = this.#options.registry.snapshot.stages.get(definition.type);
    const activated = this.#options.activated.stages.get(definition.type);
    if (!owner || !activated) throw new Error(`PIPELINE_STAGE_NOT_ACTIVATED:${definition.type}`);
    const runtime = this.#runtime(runId, state, guidance, owner);
    this.#recordAttempt(runId, state, definition.type, owner, runtime);
    let result: StageResult;
    try {
      result = await this.#invoke(activated.execute(definition.input, runtime.context, runtime.controller.signal) as Promise<StageResult>, definition.execution.timeoutMs, runtime);
      validateReferencedValue(fs.realpathSync(path.join(owner.package.root, owner.registration.resultSchema)), result, this.#options.registry.snapshot.schemas);
      this.#recordResult(runId, state.stageId, runtime.attempt.attemptId, result);
    } catch (error) {
      result = this.#failure(error);
      this.#recordResult(runId, state.stageId, runtime.attempt.attemptId, result);
    }
    finally { this.#cleanup(runtime); }
    return { ...applyStageResult(definition, { ...state, status: 'running' }, result), result };
  }

  #runtime(runId: string, state: StageRuntimeState, guidance: Readonly<Record<string, unknown>> | undefined, owner: NonNullable<ReturnType<GrantedRegistry['snapshot']['stages']['get']>>): AttemptRuntime {
    const attempt: AttemptIdentity = Object.freeze({ runId, stageId: state.stageId, attemptId: `attempt:${crypto.randomUUID()}`, attemptNumber: state.attemptNumber + 1 });
    const registrationId = `${owner.package.manifest.id}:${owner.registration.id}`;
    const definition = this.#options.graph.stage(state.stageId); const now = this.#options.now();
    const leaseContract: InvocationLease = Object.freeze({
      schemaVersion: 'invocation-lease.v2', leaseId: `lease:${crypto.randomUUID()}`, attempt, registration: owner.provenance, status: 'active',
      grants: [...(this.#options.registry.grants.get(registrationId) ?? [])],
      limits: Object.freeze({ wallTimeMs: definition.execution.timeoutMs, memoryBytes: 512 * 1024 * 1024, cpuMillis: definition.execution.timeoutMs }),
      issuedAt: now.toISOString(), expiresAt: new Date(now.getTime() + definition.execution.timeoutMs).toISOString(),
    });
    const lease = new RevocableLease(leaseContract, this.#options.now); const controller = new AbortController();
    let rejectCancellation: ((error: Error) => void) | undefined;
    const cancellation = new Promise<never>((_resolve, reject) => { rejectCancellation = reject; });
    const cancel = (): void => { controller.abort(this.#options.signal?.reason); rejectCancellation?.(new Error('PLUGIN_ATTEMPT_CANCELLED')); };
    this.#options.signal?.addEventListener('abort', cancel, { once: true }); if (this.#options.signal?.aborted) cancel();
    const context = this.#context({
      schemaVersion: 'plugin-context.v2', lease: leaseContract, config: definition.config, input: definition.input,
      ...(guidance === undefined ? {} : { guidance }),
      stageLifecycle: Object.freeze({ attemptsUsed: state.attemptsUsed, remediationCyclesUsed: state.remediationCyclesUsed,
        maxAttempts: definition.execution.maxAttempts, maxRemediationCycles: definition.execution.maxRemediationCycles }),
      artifacts: this.#priorArtifacts(runId, state.stageId),
    }, lease, owner, attempt, controller);
    return { attempt, leaseContract, lease, controller, cancellation, cancel, context };
  }

  #context(contract: PluginContext, lease: RevocableLease, owner: NonNullable<ReturnType<GrantedRegistry['snapshot']['stages']['get']>>, attempt: AttemptIdentity, controller: AbortController): ReturnType<typeof createPluginInvocationContext> {
    let sequence = 0;
    return createPluginInvocationContext(contract, lease, { invoke: async (_leaseId, capability, operation, resource, payload) => {
      sequence += 1;
      const request = { operation, resource, payload };
      const response = await this.#options.adapters.invoke(capability, attempt,
        `${attempt.runId}:${attempt.stageId}:${attempt.attemptNumber}:${sequence}`, request, controller.signal);
      if (capability === 'artifacts.write') {
        const artifact = artifactFromWrite(attempt, request, response);
        if (artifact) this.#options.checkpoints.checkpoint(artifact);
      }
      return response;
    } }, { append: async (_leaseId, type, identity, payload) => { this.#options.journal.appendSequenced((eventSequence) => ({
      schemaVersion: 'plugin-domain-event.v2', eventId: `event:${crypto.randomUUID()}`, sequence: eventSequence,
      type, producer: owner.provenance, identity, occurredAt: this.#options.now().toISOString(), causationId: attempt.attemptId, payload,
    })); } });
  }

  #priorArtifacts(runId: string, stageId: string): ArtifactRef[] {
    const visible = new Set<string>([stageId]), pending = [...this.#options.graph.stage(stageId).dependsOn];
    while (pending.length > 0) {
      const dependency = pending.pop() as string;
      if (visible.has(dependency)) continue;
      visible.add(dependency);
      pending.push(...this.#options.graph.stage(dependency).dependsOn);
    }
    return this.#options.checkpoints.artifacts(runId)
      .filter((artifact) => visible.has(artifact.producer.stageId));
  }

  #recordAttempt(runId: string, state: StageRuntimeState, stageType: string, owner: NonNullable<ReturnType<GrantedRegistry['snapshot']['stages']['get']>>, runtime: AttemptRuntime): void {
    this.#options.append('attempt.created', { runId, stageId: state.stageId, attemptId: runtime.attempt.attemptId }, { attempt: Object.freeze({
      schemaVersion: 'stage-attempt.v2', identity: runtime.attempt, owner: { ...owner.provenance.package.package, registrationId: owner.registration.id },
      stageType, leaseId: runtime.leaseContract.leaseId, status: 'created', retryBudgetUsed: state.attemptsUsed,
      remediationBudgetUsed: state.remediationCyclesUsed, createdAt: runtime.leaseContract.issuedAt,
    }), attemptNumber: runtime.attempt.attemptNumber });
    this.#options.append('attempt.dispatched', { runId, stageId: state.stageId, attemptId: runtime.attempt.attemptId });
  }

  async #invoke(operation: Promise<StageResult>, timeoutMs: number, runtime: AttemptRuntime): Promise<StageResult> {
    let timeout!: NodeJS.Timeout;
    const deadline = new Promise<never>((_, reject) => { timeout = setTimeout(() => { runtime.controller.abort(new Error('PLUGIN_ATTEMPT_TIMEOUT')); reject(new Error('PLUGIN_ATTEMPT_TIMEOUT')); }, timeoutMs); timeout.unref(); });
    try { return await Promise.race([operation, runtime.cancellation, deadline]); }
    finally { clearTimeout(timeout); }
  }

  #failure(error: unknown): StageResult {
    if (error instanceof Error && /^EFFECT_(?:OUTCOME_UNRESOLVED|RECOVERY_)/u.test(error.message)) return { schemaVersion: 'stage-result.v2', outcome: 'blocked', reason: { code: 'core.effect_reconciliation_required', message: error.message }, artifacts: [] };
    const cancelled = this.#options.signal?.aborted === true; const timedOut = error instanceof Error && error.message === 'PLUGIN_ATTEMPT_TIMEOUT';
    return { schemaVersion: 'stage-result.v2', outcome: cancelled ? 'cancelled' : timedOut ? 'timed_out' : 'retry', reason: {
      code: cancelled ? 'core.attempt_cancelled' : timedOut ? 'core.attempt_timed_out' : 'core.plugin_runtime_failed',
      message: error instanceof Error ? error.message : String(error),
    }, artifacts: [] };
  }

  #recordResult(runId: string, stageId: string, attemptId: string, result: StageResult): void {
    const type = result.outcome === 'timed_out' ? 'attempt.timed_out' : result.outcome === 'cancelled' ? 'attempt.cancelled' : 'attempt.completed';
    this.#options.append(type, { runId, stageId, attemptId }, { outcome: result.outcome, ...(result.reason ? { reason: result.reason } : {}), result: structuredClone(result) });
  }

  #cleanup(runtime: AttemptRuntime): void {
    this.#options.signal?.removeEventListener('abort', runtime.cancel); runtime.controller.abort(new Error('PLUGIN_ATTEMPT_COMPLETED'));
    runtime.lease.revoke({ code: 'core.attempt_completed' }, this.#options.now());
  }
}

import { applyRepair, repairRequest, type RepairRequest } from './remediation.ts';
import type {
  LifecycleEvent,
  PipelineDefinition,
  StageResult,
  WaitRequest,
  ResumeSignal,
} from '@kubeclaw/plugin-sdk';
import { applyStageResult, type StageRuntimeState } from './reducer.ts';
import { decisionWait } from './wait-request.ts';
import { budgetedRepairDecision } from './repair-budget.ts';
import { authorizedRepair } from './repair-authorization.ts';

type StateMap = Map<string, StageRuntimeState>;

function count(value: unknown): number {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0 ? value : 0;
}

function budgets(event: LifecycleEvent, current: StageRuntimeState): Pick<StageRuntimeState, 'attemptsUsed' | 'remediationCyclesUsed'> {
  return {
    attemptsUsed: event.payload.attemptsUsed === undefined ? current.attemptsUsed : count(event.payload.attemptsUsed),
    remediationCyclesUsed: event.payload.remediationCyclesUsed === undefined
      ? current.remediationCyclesUsed
      : count(event.payload.remediationCyclesUsed),
  };
}

export function initialStageStates(definition: PipelineDefinition): StateMap {
  return new Map([...definition.stages]
    .sort((left, right) => left.id.localeCompare(right.id))
    .map((stage) => [stage.id, {
      stageId: stage.id,
      status: 'pending' as const,
      attemptNumber: 0,
      attemptsUsed: 0,
      remediationCyclesUsed: 0,
    }]));
}

function recoverAttemptResult(
  definition: PipelineDefinition,
  event: LifecycleEvent,
  current: StageRuntimeState,
  orchestratorIssuerId: string,
  states: StateMap,
): StageRuntimeState | undefined {
  if (!['attempt.completed', 'attempt.cancelled', 'attempt.timed_out'].includes(event.type)) return undefined;
  if (!event.payload.result || typeof event.payload.result !== 'object' || current.status !== 'running') return undefined;
  const stage = definition.stages.find(({ id }) => id === current.stageId);
  if (!stage) return undefined;
  const result = event.payload.result as StageResult;
  const original = applyStageResult(stage, {
    ...current,
    attemptNumber: Math.max(0, current.attemptNumber - 1),
    attemptsUsed: Math.max(0, current.attemptsUsed - 1),
  }, result);
  const decision = budgetedRepairDecision(definition.stages, states, stage, original, result, event.identity.runId);
  const wait = decisionWait(decision, event.identity.runId, orchestratorIssuerId);
  const state = wait ? { ...decision.state, wait } : decision.state;
  if (decision.action.type === 'schedule_remediation') {
    states.set(stage.id, state);
    applyRepair(states, decision.action.repairRequest ?? repairRequest(definition.stages, stage.id,
      decision.action.stageId, state.remediationCyclesUsed, result));
    return states.get(stage.id);
  }
  return decision.action.type === 'schedule_attempt' ? { ...state, status: 'pending' } : state;
}

function scheduleState(event: LifecycleEvent, current: StageRuntimeState, states: StateMap): StageRuntimeState {
  if (typeof event.payload.remediationReturnTo === 'string') {
    return { ...current, status: 'pending', remediationReturnTo: event.payload.remediationReturnTo };
  }
  const { remediationTarget: _target, ...withoutTarget } = current;
  const remediationStageId = event.payload.remediationStageId;
  if (typeof remediationStageId === 'string') {
    const remediation = states.get(remediationStageId);
    if (remediation) {
      const { remediationReturnTo: _returnTo, ...withoutReturn } = remediation;
      states.set(remediationStageId, withoutReturn);
    }
  }
  return { ...withoutTarget, status: 'pending' };
}

function waitingState(event: LifecycleEvent, current: StageRuntimeState): StageRuntimeState {
  const wait = event.payload.wait;
  return {
    ...current,
    ...budgets(event, current),
    status: 'waiting',
    ...(wait && typeof wait === 'object' ? { wait: wait as WaitRequest } : {}),
    ...(typeof event.payload.retryAt === 'string' ? { retryAt: event.payload.retryAt } : {}),
    ...(typeof event.payload.remediationStageId === 'string'
      ? { remediationTarget: event.payload.remediationStageId }
      : {}),
  };
}

function succeededState(event: LifecycleEvent, current: StageRuntimeState): StageRuntimeState {
  const facts = event.payload.facts;
  return {
    ...current,
    ...budgets(event, current),
    status: 'succeeded',
    ...(facts && typeof facts === 'object' && !Array.isArray(facts)
      ? { facts: Object.freeze({ ...(facts as Record<string, string | number | boolean | null>) }) }
      : {}),
    ...(typeof event.payload.remediationReturnTo === 'string'
      ? { remediationReturnTo: event.payload.remediationReturnTo }
      : {}),
  };
}

const terminalStatus = new Map<string, StageRuntimeState['status']>([
  ['stage.skipped', 'skipped'],
  ['stage.blocked', 'blocked'],
  ['stage.failed', 'failed'],
  ['stage.cancelled', 'cancelled'],
]);

function stageEventState(event: LifecycleEvent, current: StageRuntimeState, states: StateMap): StageRuntimeState | undefined {
  if (event.type === 'stage.scheduled') return scheduleState(event, current, states);
  if (event.type === 'stage.started') return { ...current, status: 'running' };
  if (event.type === 'stage.retrying') return { ...current, ...budgets(event, current), status: 'pending' };
  if (event.type === 'stage.waiting' || event.type === 'orchestrator.required') return waitingState(event, current);
  if (event.type === 'stage.succeeded') return succeededState(event, current);
  const status = terminalStatus.get(event.type);
  return status ? { ...current, ...budgets(event, current), status } : undefined;
}

function resolvedWaitState(event: LifecycleEvent, current: StageRuntimeState): StageRuntimeState {
  const { wait: _wait, ...withoutWait } = current;
  const signal = event.payload.signal as ResumeSignal;
  if (!signal || signal.waitId !== event.identity.waitId) throw new Error('RECOVERY_WAIT_SIGNAL_INVALID');
  return { ...withoutWait, status: 'pending', continuationGuidance: signal.payload };
}

export function applyRecoveryEvent(
  definition: PipelineDefinition,
  states: StateMap,
  event: LifecycleEvent,
  orchestratorIssuerId: string,
): void {
  const stageId = event.identity.stageId;
  if (!stageId) return;
  const current = states.get(stageId);
  if (!current) return;
  if (event.type === 'stage.waiting' && event.payload.repairRequest) {
    states.set(stageId, { ...current, ...budgets(event, current) });
    applyRepair(states, event.payload.repairRequest as unknown as RepairRequest); return;
  }
  if (event.type === 'attempt.created') {
    const attemptNumber = count(event.payload.attemptNumber);
    states.set(stageId, { ...current, attemptNumber: Math.max(current.attemptNumber, attemptNumber), attemptsUsed: Math.max(current.attemptsUsed, attemptNumber) });
    return;
  }
  if (event.type === 'wait.resolved') {
    const repair = authorizedRepair(definition.stages, states, current, event.payload.signal as ResumeSignal);
    if (repair) { applyRepair(states, repair); return; }
    states.set(stageId, resolvedWaitState(event, current));
    return;
  }
  const recovered = recoverAttemptResult(definition, event, current, orchestratorIssuerId, states)
    ?? stageEventState(event, current, states);
  if (recovered) {
    states.set(stageId, recovered);
  }
}

export function resetInterruptedStages(states: StateMap): void {
  for (const [stageId, state] of states) {
    if (state.status === 'running') states.set(stageId, { ...state, status: 'pending' });
  }
}

import type {
  LifecycleEvent,
  PipelineDefinition,
  PluginDomainEvent,
} from '@kubeclaw/plugin-sdk';
import type { JournalRecord } from '../state/journal.ts';
import type { StageRuntimeState } from './reducer.ts';
import { FrozenMap } from '@kubeclaw/plugin-foundation/registry/frozen-map';
import { applyRecoveryEvent, initialStageStates, resetInterruptedStages } from './recovery-state.ts';

function deepFreeze<T>(value: T): T {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const nested of Object.values(value as Record<string, unknown>)) deepFreeze(nested);
  return Object.freeze(value);
}

export function recoverStageStates(
  definition: PipelineDefinition,
  records: readonly JournalRecord<LifecycleEvent | PluginDomainEvent>[],
  runId: string,
  orchestratorIssuerId: string,
): ReadonlyMap<string, StageRuntimeState> {
  const states = initialStageStates(definition);
  for (const record of records) {
    const event = record.entry;
    if (event.schemaVersion !== 'lifecycle-event.v2' || event.identity.runId !== runId) continue;
    applyRecoveryEvent(definition, states, event, orchestratorIssuerId);
  }
  resetInterruptedStages(states);
  return new FrozenMap(
    [...states].map(([stageId, state]) => [stageId, deepFreeze(structuredClone(state))]),
  );
}

/** A wait projection may be missing after a committed attempt result. Fold the
 * same reducer to recover its authoritative creation record and timestamp. */
export function recoverWaitCreation(
  definition: PipelineDefinition,
  records: readonly JournalRecord<LifecycleEvent | PluginDomainEvent>[],
  runId: string,
  orchestratorIssuerId: string,
  waitId: string,
): JournalRecord<LifecycleEvent | PluginDomainEvent> | undefined {
  const states = initialStageStates(definition);
  let created: JournalRecord<LifecycleEvent | PluginDomainEvent> | undefined;
  for (const record of records) {
    const event = record.entry;
    if (event.schemaVersion !== 'lifecycle-event.v2' || event.identity.runId !== runId) continue;
    const stageId = event.identity.stageId;
    const previous = stageId ? states.get(stageId)?.wait?.waitId : undefined;
    applyRecoveryEvent(definition, states, event, orchestratorIssuerId);
    if (stageId && previous !== waitId && states.get(stageId)?.wait?.waitId === waitId) created = record;
  }
  return created;
}

import { canonicalJson, sha256Text, type StageDefinition, type StageResult } from '@kubeclaw/plugin-sdk';
import { repairRequest, type RepairRequest } from './remediation.ts';
import type { LifecycleDecision, StageRuntimeState } from './reducer.ts';

export interface RepairOrder {
  readonly id: string;
  readonly category: string;
  readonly requesterStageId: string;
  readonly requesterAttempt: number;
  readonly requestDigest: string;
  readonly request: RepairRequest;
  readonly sourceFacts: Readonly<Record<string, string | number | boolean | null>>;
  readonly authorization?: Readonly<{ signalId: string; reason: string }>;
}

export interface PendingRepair {
  readonly digest: string;
  readonly category: string;
  readonly request: RepairRequest;
  readonly history: readonly RepairOrder[];
  readonly sourceFacts: Readonly<Record<string, string | number | boolean | null>>;
}

export function repairOrder(pending: PendingRepair, attempt: number): RepairOrder {
  return { id: pending.digest, category: pending.category, requesterStageId: pending.request.requesterStageId,
    requesterAttempt: attempt, requestDigest: pending.digest, request: pending.request, sourceFacts: pending.sourceFacts };
}

export function pendingRepair(
  stages: readonly StageDefinition[], states: ReadonlyMap<string, StageRuntimeState>,
  requester: StageDefinition, state: StageRuntimeState, result: StageResult, runId: string,
): PendingRepair {
  const target = requester.on!.request_fix!;
  const request = repairRequest(stages, requester.id, target, state.remediationCyclesUsed, result);
  const category = requester.execution.repairCategory!;
  const history = states.get(target)?.repairLedger ?? [];
  const sourceFacts = states.get(target)?.facts ?? {};
  return { digest: sha256Text(canonicalJson({ runId, category, request, history, sourceFacts })), category, request, history, sourceFacts };
}

export function repairDisposition(stages: readonly StageDefinition[], pending: PendingRepair): 'allowed' | 'authorize' | 'blocked' {
  const policy = stages.find(stage => stage.id === pending.request.targetStageId)?.execution.repairBudget;
  if (!policy || policy.categories[pending.category] === undefined) throw new Error('REPAIR_BUDGET_UNDECLARED');
  const authorized = pending.history.filter(order => order.authorization).length;
  // Once an extra order was issued, any later repair requires operator action.
  if (authorized > 0) return 'blocked';
  if (pending.history.filter(order => order.category === pending.category).length < policy.categories[pending.category]!) return 'allowed';
  return authorized < policy.maximumOrchestratorOrders ? 'authorize' : 'blocked';
}

/** The same policy projects an original completion in live execution and replay. */
export function budgetedRepairDecision(
  stages: readonly StageDefinition[], states: ReadonlyMap<string, StageRuntimeState>, requester: StageDefinition,
  decision: LifecycleDecision, result: StageResult, runId: string,
): LifecycleDecision {
  const owner = requester.execution.repairBudget ? requester.id : requester.on?.request_fix;
  if (decision.state.status === 'failed' && owner
    && states.get(owner)?.repairLedger?.some(order => order.authorization)) {
    return { state: { ...decision.state, status: 'blocked' }, action: { type: 'stop' } };
  }
  if (!requester.execution.repairCategory || decision.action.type !== 'schedule_remediation') return decision;
  const pending = pendingRepair(stages, states, requester, decision.state, result, runId);
  const disposition = repairDisposition(stages, pending);
  if (disposition === 'allowed') return { ...decision, action: { ...decision.action,
    repairRequest: { ...pending.request, budgetOrder: repairOrder(pending, decision.state.attemptNumber) } } };
  const { remediationTarget: _target, ...withoutTarget } = decision.state;
  return { state: { ...withoutTarget, status: disposition === 'authorize' ? 'waiting' : 'blocked', pendingRepair: pending },
    action: disposition === 'authorize' ? { type: 'request_repair_authorization', pending } : { type: 'stop' } };
}

export function recordRepairOrder(states: Map<string, StageRuntimeState>, request: RepairRequest): void {
  if (!request.budgetOrder) return;
  const target = states.get(request.targetStageId)!;
  const ledger = target.repairLedger ?? [];
  const existing = ledger.find(order => order.id === request.budgetOrder!.id);
  if (existing) {
    if (canonicalJson(existing) !== canonicalJson(request.budgetOrder)) throw new Error('REPAIR_ORDER_IDENTITY_CONFLICT');
    return;
  }
  states.set(request.targetStageId, { ...target, repairLedger: [...ledger, request.budgetOrder] });
}
